<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { call, createResource, toast } from 'frappe-ui'
import { statusPillClass } from '../data/bstkStatus'
import { currentUser } from '../data/user'
import { refreshCsrfToken } from '../data/session'
import { openAttachment, openPdf } from '../composables/pdfViewer'
import { useBackNavigation } from '../composables/useBackNavigation'
import { kompresFoto } from '../composables/imageCompress'
import FotoBstkCollapse from '../components/FotoBstkCollapse.vue'

const DOCTYPE = 'BSTK'
const route = useRoute()
const { backTarget, backLabel } = useBackNavigation({ name: 'Bstk' }, 'BSTK')
const name = computed(() => route.params.name)

const displayTitle = computed(() => doc.data?.name || name.value)

// ---- Aksi dokumen ----------------------------------------------------------
// Tombol "Action" menampung tiga aksi yang sama dengan form BSTK di desk:
//   Close BSTK -> bstk.js
//   Oper PIC   -> public/js/oper_pic_actions.js
//   Regis      -> public/js/monitoring_document_actions.js
// Syaratnya sengaja TIDAK dihitung ulang di sini: portal memakai state yang
// dikirim server (get_oper_pic_state / get_status_monitoring_doc) supaya
// aturannya tidak bercabang antara desk dan portal. Yang dicerminkan di klien
// hanya tipe close per role — persis tipe_options() di close_document_dialog.js.
const ADMIN_CLOSE_ROLES = ['System Manager', 'Admin Coll', 'Head Admin Coll']
const FIELD_ROLES = ['Field Coll', 'Head Field Coll']
const ALL_CLOSE_TYPES = ['Dipakai', 'Rusak', 'Hilang']

// Role belum termuat (atau fetch-nya gagal) bukan alasan menyembunyikan aksi:
// server tetap menolak yang tidak berhak, sedangkan menyembunyikan tombol dari
// orang yang berhak tidak bisa dipulihkan sendiri oleh pemakainya.
const rolesUnknown = computed(() => !currentUser.rolesLoaded || !currentUser.roles.length)
function hasAnyRole(list) {
	return list.some((r) => currentUser.roles.includes(r))
}
const closeTypeOptions = computed(() => {
	if (rolesUnknown.value || hasAnyRole(ADMIN_CLOSE_ROLES)) return ALL_CLOSE_TYPES
	if (hasAnyRole(FIELD_ROLES)) return ['Dipakai']
	return []
})

// BSTK bisa di-close HANYA saat status "Belum Terpakai" (sudah diregistrasi ke
// kolektor). Selaras backend close_bstk() yang menolak selain status ini pada
// jalur "Melalui Registrasi" — satu-satunya jalur yang dipakai portal.
const canClose = computed(
	() => doc.data?.status === 'Belum Terpakai' && closeTypeOptions.value.length > 0
)

// State aksi dari server; keputusan finalnya tetap di endpoint masing-masing.
const operState = reactive({
	can_submit: false,
	direct_by_admin: false,
	current_pic: '',
	current_nama_pic: '',
	// Pengajuan yang masih menunggu + apakah user ini boleh memutuskannya.
	// Server sudah menolak pengaju menyetujui pengajuannya sendiri, jadi
	// can_review sekaligus menyembunyikan tombol yang pasti gagal.
	can_review: false,
	pending: null,
})
const monState = reactive({ can_report: false })
// Cancel adalah transisi "BSTK Close Workflow": status mana yang bisa di-cancel
// dan siapa yang boleh ditentukan di sana, jadi portal menanyakannya ke server
// alih-alih menyalin aturannya — sama seperti Oper PIC & Regis.
const cancelState = reactive({ can_cancel: false, next_state: null })
const canCancel = computed(() => cancelState.can_cancel)

async function loadActionState() {
	const [oper, mon, cancel] = await Promise.all([
		// Ketiganya melempar PermissionError untuk yang tidak berhak — itu jawaban
		// yang sah ("tidak ada aksi"), bukan kegagalan halaman.
		call('juragan.collection.oper_pic.get_oper_pic_state', {
			doctype: DOCTYPE,
			name: name.value,
		}).catch(() => null),
		call('juragan.collection.monitoring_dokumen.get_status_monitoring_doc', {
			doctype: DOCTYPE,
			name: name.value,
		}).catch(() => null),
		call('juragan.collection.doctype.bstk.bstk.get_cancel_state', {
			nomor_bstk: name.value,
		}).catch(() => null),
	])
	operState.can_submit = !!oper?.can_submit
	operState.direct_by_admin = !!oper?.direct_by_admin
	operState.current_pic = oper?.current_pic || ''
	operState.current_nama_pic = oper?.current_nama_pic || ''
	operState.can_review = !!oper?.can_review
	operState.pending = oper?.pending || null
	monState.can_report = !!mon?.can_report
	cancelState.can_cancel = !!cancel?.can_cancel
	cancelState.next_state = cancel?.next_state || null
}

const actions = computed(() => {
	const list = []
	if (canClose.value) list.push({ key: 'close', label: 'Close BSTK' })
	if (canCancel.value) list.push({ key: 'cancel', label: 'Cancel BSTK' })
	if (operState.can_submit)
		list.push({
			key: 'oper',
			label: operState.direct_by_admin ? 'Oper PIC' : 'Ajukan Oper PIC',
		})
	// Saat ada pengajuan menggantung, can_submit pasti false — jadi kedua entri
	// ini tidak pernah muncul bersamaan. Labelnya sengaja sama: satu pintu
	// "Oper PIC", isinya menyesuaikan keadaan dokumen.
	if (operState.can_review) list.push({ key: 'oper_review', label: 'Oper PIC' })
	if (monState.can_report) list.push({ key: 'regis', label: 'Regis' })
	return list
})
const hasActions = computed(() => actions.value.length > 0)

const actionOpen = ref(false)
function openActions() {
	actionOpen.value = true
}
function runAction(key) {
	actionOpen.value = false
	if (key === 'close') openClose()
	else if (key === 'cancel') openCancel()
	else if (key === 'oper') openOper()
	else if (key === 'oper_review') openReview()
	else if (key === 'regis') openRegis()
}

// ---- Download PDF ----
// Mengikuti bstk.js desk: BSTK me-render print format langsung (BUKAN signed PDF
// seperti Deviasi/Diskresi/AYDA/Tebus), dan tombolnya TANPA syarat status —
// tampil untuk setiap dokumen yang sudah tersimpan (`if (frm.is_new()) return`).
const BSTK_PRINT_FORMAT = 'Form BSTK KSP COLL'
const showPdf = computed(() => !!doc.data?.name)

// Dibuka lewat PdfViewer in-app (PDF.js), bukan window.open seperti desk:
// endpoint download_pdf mengirim Content-Disposition attachment & WebView
// Android tak punya renderer PDF → window.open hanya menghasilkan halaman kosong.
function openBstkPdf() {
	const url =
		`/api/method/frappe.utils.print_format.download_pdf` +
		`?doctype=${encodeURIComponent(DOCTYPE)}` +
		`&name=${encodeURIComponent(name.value)}` +
		`&format=${encodeURIComponent(BSTK_PRINT_FORMAT)}` +
		`&no_letterhead=0`
	openPdf(url, `BSTK ${name.value}`)
}

// Eksekutor Eksternal (BTM/TPI) → Nama PIC wajib diisi manual saat close Dipakai.
// Internal → Nama PIC di-resolve server dari data registrasi.
const isEksternal = computed(() => !!doc.data?.eksekutor && doc.data.eksekutor !== 'Internal')

// Toast frappe-ui tak auto-dismiss di webview → hapus manual.
function autoToast(type, message) {
	const id = toast[type](message)
	setTimeout(() => toast.remove(id), 3500)
}

// ---- Close BSTK ------------------------------------------------------------
const CLOSE_TYPES = [
	{
		key: 'Dipakai',
		label: 'Dipakai',
		iconWrap: 'bg-ui-surface-green-100 text-ui-ink-green-600',
	},
	{ key: 'Rusak', label: 'Rusak', iconWrap: 'bg-ui-surface-red-100 text-ui-ink-red-600' },
	{ key: 'Hilang', label: 'Hilang', iconWrap: 'bg-ui-surface-gray-200 text-ui-ink-gray-600' },
]
// Kolektor lapangan hanya boleh tipe Dipakai — menampilkan Rusak/Hilang untuk
// mereka hanya berujung penolakan server.
const visibleCloseTypes = computed(() =>
	CLOSE_TYPES.filter((t) => closeTypeOptions.value.includes(t.key))
)
const closeOpen = ref(false)
const selectedType = ref('')
const submitting = ref(false)
const closeError = ref('')

// Form Close: field yang dipakai backend close_bstk.
// Kelengkapan unit, kategori, dan foto mengikuti dialog Close BSTK di desk.
const form = reactive({
	no_perjanjian: '',
	tanggal_bstk: '',
	nama_pic: '',
	kunci: 0,
	stnk: 0,
	keterangan_stnk: '',
	kategori: '',
	tanggal_janji_tebus: '',
	foto_bstk: [],
	keterangan: '',
})
const KATEGORI_OPTIONS = ['Janji Tebus', 'Tarik Putus']

// File untuk Rusak (foto) / Hilang (dokumen STPL).
const fileInput = ref(null)
const pickedFile = ref(null)
const fileName = computed(() => pickedFile.value?.name || '')
const fileAccept = computed(() => (selectedType.value === 'Rusak' ? 'image/*' : '.pdf,image/*'))

// ---- Konteks No Perjanjian dari Aktivitas Field Collection -----------------
// Bila BSTK ini sudah dipakai pada input aktivitas Field Coll (Target dan
// Realisasi), No Perjanjian-nya diisi otomatis & dikunci. No Perjanjian yang
// sudah diklaim aktivitas lain dibuang dari hasil pencarian manual.
// Sama persis dgn perilaku dialog Close BSTK di desk (bstk.js).
const closeCtx = reactive({ auto: '', claimed: [] })
const ctxLoading = ref(false)
const lockedNoPerjanjian = computed(() => !!closeCtx.auto)

async function loadCloseContext() {
	closeCtx.auto = ''
	closeCtx.claimed = []
	ctxLoading.value = true
	try {
		const r = await call(
			'juragan.api.local.utils_collection.get_close_no_perjanjian_context',
			{
				document_doctype: DOCTYPE,
				document: name.value,
			}
		)
		closeCtx.auto = r?.auto || ''
		closeCtx.claimed = r?.claimed || []
		if (closeCtx.auto) await selectNasabah({ name: closeCtx.auto })
	} catch (e) {
		/* konteks gagal → user tetap bisa pilih No Perjanjian manual */
	} finally {
		ctxLoading.value = false
	}
}

// Cari No Perjanjian + preview info nasabah.
const searchQuery = ref('')
const searchOpen = ref(false)
const searching = ref(false)
const searchResults = ref([])
let searchTimer = null
const preview = reactive({ nama_nasabah: '', nopol: '', angsuran_ke: '', bucket: '' })
const previewLoading = ref(false)
const previewRows = computed(() => [
	{ label: 'Nama Nasabah', value: preview.nama_nasabah || '—' },
