// ---- Dropdown di dalam bottom sheet ----------------------------------------
// Daftar hasil MELAYANG di luar sheet (position: fixed) dan posisinya dihitung
// dari kotak kolomnya, jadi tinggi sheet tidak ikut berubah saat daftar dibuka.
// Arahnya ke ATAS begitu ruang di bawah tidak cukup — di sheet yang menempel
// tepi bawah layar itu keadaan yang biasa, dan daftar yang jatuh ke bawah akan
// keluar layar. Tinggi maksimalnya juga dipotong sesuai ruang yang tersedia
// supaya tidak pernah ada bagian yang tidak bisa dijangkau.
const TINGGI_DROPDOWN = 208 // setara max-h-52
const JARAK_DROPDOWN = 4
const npBox = ref(null)
const picBox = ref(null)
const npStyle = ref({})
const picStyle = ref({})

function posisiDropdown(el) {
	if (!el) return {}
	const r = el.getBoundingClientRect()
	const ruangBawah = window.innerHeight - r.bottom
	const dasar = { left: `${r.left}px`, width: `${r.width}px` }
	if (ruangBawah < TINGGI_DROPDOWN + JARAK_DROPDOWN && r.top > ruangBawah) {
		return {
			...dasar,
			bottom: `${window.innerHeight - r.top + JARAK_DROPDOWN}px`,
			maxHeight: `${Math.max(96, Math.min(TINGGI_DROPDOWN, r.top - 12))}px`,
		}
	}
	return {
		...dasar,
		top: `${r.bottom + JARAK_DROPDOWN}px`,
		maxHeight: `${Math.max(96, Math.min(TINGGI_DROPDOWN, ruangBawah - 12))}px`,
	}
}

function ukurNp() {
	npStyle.value = posisiDropdown(npBox.value)
}
function ukurPic() {
	picStyle.value = posisiDropdown(picBox.value)
}

