async function submitClose() {
	if (!selectedType.value || submitting.value) return
	closeError.value = ''

	if (selectedType.value === 'Dipakai') {
		if (!form.no_perjanjian.trim()) return (closeError.value = 'No Perjanjian wajib diisi.')
		if (!form.tanggal_bstk) return (closeError.value = 'Tanggal BSTK wajib diisi.')
		if (isEksternal.value && !form.nama_pic.trim())
			return (closeError.value = 'Nama PIC wajib diisi untuk eksekutor eksternal.')
		// Cerminan mandatory_depends_on di dialog desk: keterangan wajib hanya
		// saat unit diserahkan tanpa STNK.
		if (!form.stnk && !form.keterangan_stnk.trim())
			return (closeError.value = 'Keterangan STNK wajib diisi bila STNK tidak ada.')
	} else if (!pickedFile.value) {
		return (closeError.value =
			selectedType.value === 'Rusak'
				? 'Foto bukti wajib diunggah.'
				: 'Dokumen STPL wajib diunggah.')
	}

	submitting.value = true
	try {
		const args = {
			nomor_bstk: name.value,
			tipe_close: selectedType.value,
			keterangan: form.keterangan.trim(),
		}
		if (selectedType.value === 'Dipakai') {
			args.no_perjanjian = form.no_perjanjian.trim()
			args.tanggal_bstk = form.tanggal_bstk
			if (isEksternal.value) args.nama_pic = form.nama_pic.trim()
			args.kunci = form.kunci ? 1 : 0
			args.stnk = form.stnk ? 1 : 0
			args.keterangan_stnk = form.keterangan_stnk.trim()
			args.kategori = form.kategori
			// Server mengabaikan tanggalnya bila kategorinya bukan Janji Tebus.
			args.tanggal_janji_tebus = form.tanggal_janji_tebus
			args.foto_bstk = JSON.stringify(form.foto_bstk || [])
		} else {
			const fileUrl = await uploadRawFile(pickedFile.value)
			if (!fileUrl) throw new Error('Upload file gagal.')
			if (selectedType.value === 'Rusak') args.foto_rusak = fileUrl
			else args.dokumen_stpl = fileUrl
		}
		const r = await call('juragan.collection.doctype.bstk.bstk.close_bstk', args)
		closeOpen.value = false
		doc.fetch()
		await loadActionState()
		autoToast('success', r?.message || 'Close BSTK berhasil.')
	} catch (e) {
		closeError.value =
			e?.messages?.[0] || e?.message || String(e) || 'Gagal melakukan Close BSTK.'
	} finally {
		submitting.value = false
	}
}

