const regisOpen = ref(false)
const regisSubmitting = ref(false)
const regisError = ref('')
const regisCatatan = ref('')
const regisFotoInput = ref(null)
const regisFoto = ref(null)
const regisFotoPreview = ref('')
const regisFotoProses = ref(false)

// Foto di atas batas dikompres otomatis (lihat kompresFoto), bukan ditolak.
const MAX_FOTO_MB = 3

function bersihkanFotoRegis() {
	if (regisFotoPreview.value) URL.revokeObjectURL(regisFotoPreview.value)
	regisFotoPreview.value = ''
	regisFoto.value = null
}

// Mobile: serahkan ke aplikasi kamera lewat input bertanda `capture` — jalur ini
// tetap bekerja di WebView APK. Desktop: atribut `capture` diabaikan browser dan
// yang terbuka justru file explorer, jadi di sana kamera dibuka in-page.
function ambilFotoRegis() {
	if (perangkatMobile()) regisFotoInput.value?.click()
	else bukaKamera()
}

const camOpen = ref(false)
const camVideo = ref(null)
const camError = ref('')
const camSiap = ref(false)
let camStream = null

function perangkatMobile() {
	return /android|iphone|ipad|ipod|mobile/i.test(navigator.userAgent)
}

async function bukaKamera() {
	if (!navigator.mediaDevices?.getUserMedia) {
		regisError.value = 'Perangkat ini tidak menyediakan akses kamera.'
		return
	}
	camError.value = ''
	camSiap.value = false
	camOpen.value = true
	await nextTick()
	try {
		camStream = await navigator.mediaDevices.getUserMedia({
			video: { facingMode: 'environment' },
			audio: false,
		})
		if (camVideo.value) {
			camVideo.value.srcObject = camStream
			await camVideo.value.play().catch(() => {})
		}
		camSiap.value = true
	} catch (e) {
		camError.value = 'Kamera tidak bisa dibuka. Pastikan izin kamera diberikan.'
	}
}

function tutupKamera() {
	if (camStream) {
		camStream.getTracks().forEach((t) => t.stop())
		camStream = null
	}
	camSiap.value = false
	camOpen.value = false
}

function jepretFoto() {
	const video = camVideo.value
	if (!video || !video.videoWidth) return
	const canvas = document.createElement('canvas')
	canvas.width = video.videoWidth
	canvas.height = video.videoHeight
	canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height)
	canvas.toBlob(
		(blob) => {
			if (!blob) return
			tutupKamera()
			pasangFotoRegis(new File([blob], `regis_${Date.now()}.jpg`, { type: 'image/jpeg' }))
		},
		'image/jpeg',
		0.9
	)
}

onBeforeUnmount(tutupKamera)

function onRegisFotoChange(e) {
	const f = e.target.files?.[0]
	e.target.value = '' // izinkan ambil ulang foto
	if (f) pasangFotoRegis(f)
}

async function pasangFotoRegis(f) {
	regisFotoProses.value = true
	regisError.value = ''
	try {
		const hasil = await kompresFoto(f, MAX_FOTO_MB * 1024 * 1024)
		if (!hasil) {
			regisError.value = `Foto tidak bisa diperkecil ke ${MAX_FOTO_MB} MB. Coba ambil ulang.`
			return
		}
		bersihkanFotoRegis()
		regisFoto.value = hasil
		regisFotoPreview.value = URL.createObjectURL(hasil)
	} finally {
		regisFotoProses.value = false
	}
}

function openRegis() {
	regisCatatan.value = ''
	regisError.value = ''
	bersihkanFotoRegis()
	regisOpen.value = true
}
function closeRegisSheet() {
	tutupKamera()
	regisOpen.value = false
}

async function submitRegis() {
	if (regisSubmitting.value) return
	// Foto wajib — server juga menolaknya, tapi dicek di sini supaya PIC tahu
	// sebelum sheet-nya terkirim (dan catatan yang sudah diketik tidak hilang).
	if (!regisFoto.value) {
		regisError.value = 'Foto dokumen wajib diambil.'
		return
	}
	regisSubmitting.value = true
	regisError.value = ''
	try {
		// Foto diunggah lebih dulu; server hanya menerima file_url-nya.
		const foto = await uploadRawFile(regisFoto.value)
		const r = await call('juragan.collection.monitoring_dokumen.submit_laporan_pic', {
			items: [
				{
					doctype: DOCTYPE,
					name: name.value,
					catatan_pic: regisCatatan.value.trim(),
