				},
			],
		})
		regisOpen.value = false
		bersihkanFotoRegis()
		doc.fetch()
		await loadActionState()
		autoToast('success', r?.message || 'Laporan terkirim.')
	} catch (e) {
		regisError.value = e?.messages?.[0] || e?.message || String(e) || 'Gagal mengirim laporan.'
	} finally {
		regisSubmitting.value = false
	}
}

