	cancelSubmitting.value = true
	cancelError.value = ''
	try {
		const r = await call('juragan.collection.doctype.bstk.bstk.cancel_bstk', {
			nomor_bstk: name.value,
			alasan: cancelAlasan.value.trim(),
		})
		cancelOpen.value = false
		doc.fetch()
		await loadActionState()
		autoToast('success', r?.message || 'BSTK dibatalkan.')
	} catch (e) {
		cancelError.value =
			e?.messages?.[0] || e?.message || String(e) || 'Gagal melakukan cancel.'
	} finally {
		cancelSubmitting.value = false
	}
}

// ---- Fetch dokumen ---------------------------------------------------------
const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: DOCTYPE, name: name.value }
	},
	auto: false,
})

// ---- Meta doctype ----------------------------------------------------------
const metaFields = ref([])

const SKIP_TYPES = [
	'Section Break',
	'Column Break',
	'Tab Break',
	'HTML',
	'Button',
	'Heading',
	'Fold',
	'Barcode',
	// Tabel anak tidak punya bentuk tampilan di kartu detail; kalau ikut
	// dirender nilainya jadi "[object Object]".
	'Table',
	'Table MultiSelect',
]
const STRUCT_TYPES = ['Section Break', 'Column Break', 'Tab Break']

function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text', 'Code', 'Text Editor'].includes(ft)
}
function isImageField(ft) {
	return ['Image', 'Attach Image'].includes(ft)
}

// ---- Format nilai ----------------------------------------------------------
function isEmpty(v) {
	return v == null || (typeof v === 'string' && v.trim() === '')
}
function formatDate(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
function formatNumber(v) {
	const n = Number(v)
	return Number.isNaN(n) ? String(v) : new Intl.NumberFormat('id-ID').format(n)
}
function formatCurrency(v) {
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return `Rp ${new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 0,
		maximumFractionDigits: 2,
	}).format(n)}`
}
function valueDisplay(field, v) {
	if (field.fieldtype === 'Check') return v ? 'Ya' : 'Tidak'
	if (isEmpty(v)) return '—'
	switch (field.fieldtype) {
		case 'Currency':
			return formatCurrency(v)
		case 'Date':
		case 'Datetime':
			return formatDate(v)
		case 'Float':
		case 'Int':
		case 'Percent':
			return formatNumber(v)
		default:
			return String(v)
	}
}
function hasValue(field, v) {
	if (field.fieldtype === 'Check') return !!v
	return !isEmpty(v)
}

// ---- Susun tab → item (section) dari meta -----------------------------------
const tabsStructure = computed(() => {
	const tabs = []
	let curTab = null
	let curSection = null
	let curCol = null

	const ensureTab = () => {
		if (!curTab) {
			curTab = { key: '__detail__', label: 'Detail', items: [] }
			tabs.push(curTab)
		}
	}
	const ensureSection = () => {
		if (!curSection) {
			curCol = []
			curSection = { type: 'section', label: '', columns: [curCol] }
			curTab.items.push(curSection)
		}
	}

	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			curTab = { key: f.fieldname, label: f.label || f.fieldname, items: [] }
			tabs.push(curTab)
			curSection = null
			curCol = null
			continue
		}
		ensureTab()
		if (ft === 'Section Break') {
			curCol = []
			curSection = { type: 'section', label: f.label || '', columns: [curCol] }
			curTab.items.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) ensureSection()
			else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (SKIP_TYPES.includes(ft) || f.hidden) continue
		ensureSection()
		curCol.push(f)
	}
	return tabs
})

// Tab + section yang BENAR-BENAR punya data (sembunyikan field/section kosong).
const renderedTabs = computed(() => {
	const data = doc.data || {}
	const out = []
	for (const tab of tabsStructure.value) {
		const items = []
		for (const item of tab.items) {
			if (item.type === 'section') {
				const columns = item.columns
					.map((col) => col.filter((f) => hasValue(f, data[f.fieldname])))
					.filter((col) => col.length)
				if (columns.length) items.push({ ...item, columns })
			}
		}
		if (items.length) out.push({ key: tab.key, label: tab.label, items })
	}
	return out
})

// Semua section diratakan → langsung heading + card, tanpa sub-tab.
//
// Saat status masih "Stok" (belum diregistrasi), section Registrasi &
// Informasi Close belum relevan → tampilkan HANYA card Informasi BSTK.
const HIDE_SECTIONS_WHEN_STOCK = ['Registrasi', 'Informasi Close']
// Riwayat Oper PIC dipakai untuk audit di desk; di portal section-nya tidak
// ditampilkan supaya halaman detail tetap ringkas.
const HIDE_SECTIONS = ['Oper PIC']
const allSections = computed(() => {
	const secs = renderedTabs.value
		.flatMap((t) => t.items)
		.filter((s) => !HIDE_SECTIONS.includes(s.label))
	if (doc.data?.status === 'Stok') {
		return secs.filter((s) => !HIDE_SECTIONS_WHEN_STOCK.includes(s.label))
	}
	return secs
})

// ---- Muat meta -------------------------------------------------------------
async function fetchDoctypeMeta(dt) {
	const res = await fetch(
		`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(dt)}`,
		{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
	)
	if (!res.ok) throw new Error(`HTTP ${res.status}`)
	const json = await res.json()
	const docs = json.docs || json.message?.docs || []
	const meta = docs.find((x) => x.name === dt) || docs[0]
	return (meta && meta.fields) || []
}

async function loadMeta() {
	try {
		metaFields.value = await fetchDoctypeMeta(DOCTYPE)
	} catch (e) {
		/* meta gagal → tab tidak terbentuk, dokumen tetap tampil kosong */
	}
}

const headerRef = ref(null)
onMounted(async () => {
	await refreshCsrfToken()
	doc.fetch()
	loadActionState()
	await loadMeta()
})
</script>
